<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {request,RequestError} from '../../../api/client'
import {useSession} from '../../../stores/session'
import type {components} from '../../../api/generated/schema'
import {ElTable,ElTableColumn,ElButton,ElInput,ElInputNumber,ElSelect,ElOption,ElTag} from 'element-plus'
import 'element-plus/dist/index.css'
type Document=components['schemas']['StockDocument']
const store=useSession(),items=ref<Document[]>([]),next=ref(''),q=ref(''),status=ref(''),direction=ref(''),busy=ref(false),error=ref(''),creating=ref(false),reviewing=ref<Document>(),approve=ref(true),reason=ref('')
const form=ref<components['schemas']['StockDocumentInput']>({direction:'IN',stock_kind:'PHYSICAL',items:[{product_id:'',quantity:1}],note:''})
const canWrite=computed(()=>store.session?.permissions.includes('inventory.write')),canApprove=computed(()=>store.session?.permissions.includes('inventory.approve'))
const pending=ref<{path:string;body:string;key:string}>()
function message(e:unknown){return e instanceof RequestError?({'OUT_OF_STOCK':'可用库存不足，审核未生效','VERSION_CONFLICT':'单据已变化，请刷新后重新审核','ILLEGAL_TRANSITION':'单据已审核，不能再次操作','FORBIDDEN':'没有操作权限','VALIDATION_FAILED':'请检查商品 ID、数量和凭证','IDEMPOTENCY_CONFLICT':'请求标识冲突'}[e.detail.code]??'操作失败，请重试'):'网络异常，可重试原请求'}
async function load(after=''){busy.value=true;error.value='';try{const p=new URLSearchParams({limit:'20',q:q.value,status:status.value});if(direction.value)p.set('direction',direction.value);if(after)p.set('after_id',after);const r=await request<components['schemas']['StockDocumentList']>('/api/v1/admin/inventory/documents?'+p);items.value=r.items;next.value=r.next_after_id??''}catch(e){error.value=message(e)}finally{busy.value=false}}
function review(d:Document,yes:boolean){reviewing.value=d;approve.value=yes;reason.value=''}
async function submit(){if(!pending.value){if(reviewing.value&&!approve.value&&!reason.value.trim()){error.value='拒绝必须填写原因';return};pending.value={path:reviewing.value?'/api/v1/admin/inventory/documents/'+reviewing.value.id+'/'+(approve.value?'approve':'reject'):'/api/v1/admin/inventory/documents',body:JSON.stringify(reviewing.value?{version:reviewing.value.version,reason:reason.value}:form.value),key:crypto.randomUUID()}}
 busy.value=true;error.value='';try{await request(pending.value.path,{method:'POST',body:pending.value.body},pending.value.key);pending.value=undefined;creating.value=false;reviewing.value=undefined;form.value={direction:'IN',stock_kind:'PHYSICAL',items:[{product_id:'',quantity:1}],note:''};await load()}catch(e){error.value=message(e);if(e instanceof RequestError&&e.status<500){pending.value=undefined;if(e.status===409)reviewing.value=undefined}}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><main class="admin-page"><div class="page-title"><h1>入出库单与审核</h1><RouterLink to="/admin">工作台</RouterLink><RouterLink to="/admin/inventory">库存余额 / 流水</RouterLink><ElButton v-if="canWrite" :disabled="busy||!!pending||!!reviewing" @click="creating=true">新建单据</ElButton></div><form class="filters" @submit.prevent="load()"><ElInput v-model="q" maxlength="100" placeholder="单号或备注"/><ElSelect v-model="status" aria-label="单据状态"><ElOption label="全部状态" value=""/><ElOption label="待审核" value="PENDING"/><ElOption label="已批准" value="APPROVED"/><ElOption label="已拒绝" value="REJECTED"/></ElSelect><ElSelect v-model="direction" aria-label="单据方向"><ElOption label="全部方向" value=""/><ElOption label="入库" value="IN"/><ElOption label="出库" value="OUT"/></ElSelect><ElButton native-type="submit" :loading="busy">查询</ElButton></form><p v-if="error" role="alert">{{error}}</p><form v-if="creating" @submit.prevent="submit"><fieldset :disabled="!!pending||busy"><legend>新建库存单</legend><label>方向 <ElSelect v-model="form.direction"><ElOption label="入库" value="IN"/><ElOption label="出库" value="OUT"/></ElSelect></label><label>类型 <ElSelect v-model="form.stock_kind"><ElOption label="实物" value="PHYSICAL"/><ElOption label="虚拟" value="VIRTUAL"/></ElSelect></label><p>商品 ID 可在商品管理中查看。单据批准后才变更库存。</p><div v-for="(line,i) in form.items" :key="i" class="filters"><label>商品 ID <ElInput v-model="line.product_id" required pattern="[1-9][0-9]*"/></label><label>数量 <ElInputNumber v-model="line.quantity" :min="1" :max="100000" :precision="0"/></label><ElButton :disabled="form.items.length===1" @click="form.items.splice(i,1)">移除</ElButton></div><ElButton :disabled="form.items.length>=100" @click="form.items.push({product_id:'',quantity:1})">添加商品</ElButton><label>备注 <ElInput v-model="form.note" type="textarea" maxlength="500"/></label><label>图片凭证 ID（可选） <ElInput :model-value="form.proof_file_id??''" @update:model-value="v=>{if(v)form.proof_file_id=String(v);else delete form.proof_file_id}"/></label></fieldset><ElButton native-type="submit" :loading="busy">{{pending?'重试原请求':'提交待审核'}}</ElButton><ElButton v-if="!pending" @click="creating=false">取消</ElButton></form><form v-if="reviewing" @submit.prevent="submit"><h2>{{approve?'批准':'拒绝'}} {{reviewing.document_no}}</h2><p>{{reviewing.direction==='IN'?'入库':'出库'}}：{{reviewing.items.map(l=>'商品 '+l.product_id+' × '+l.quantity).join('，')}}</p><ElInput v-model="reason" maxlength="200" placeholder="审核原因（拒绝必填）" :disabled="!!pending"/><ElButton native-type="submit" :loading="busy">{{pending?'重试原请求':'确认审核'}}</ElButton><ElButton v-if="!pending" @click="reviewing=undefined">取消</ElButton></form><ElTable :data="items" empty-text="暂无库存单"><ElTableColumn prop="document_no" label="单号"/><ElTableColumn label="方向 / 类型"><template #default="{row}">{{row.direction==='IN'?'入库':'出库'}} / {{row.stock_kind==='PHYSICAL'?'实物':'虚拟'}}</template></ElTableColumn><ElTableColumn label="商品 / 数量"><template #default="{row}"><div v-for="l in row.items" :key="l.product_id">{{l.product_id}} × {{l.quantity}}</div></template></ElTableColumn><ElTableColumn prop="note" label="备注"/><ElTableColumn label="状态"><template #default="{row}"><ElTag>{{({PENDING:'待审核',APPROVED:'已批准',REJECTED:'已拒绝'} as Record<string,string>)[row.state]}}</ElTag></template></ElTableColumn><ElTableColumn v-if="canApprove" label="审核"><template #default="{row}"><ElButton :disabled="row.state!=='PENDING'||busy||!!pending||creating" @click="review(row,true)">批准</ElButton><ElButton :disabled="row.state!=='PENDING'||busy||!!pending||creating" @click="review(row,false)">拒绝</ElButton></template></ElTableColumn></ElTable><ElButton v-if="next" :disabled="busy" @click="load(next)">下一页</ElButton><ElButton :disabled="busy" @click="load()">刷新 / 首页</ElButton></main></template>
